import {ITEMS,heldItems} from './model.mjs';
import {bagHTML} from './resources.mjs';
const owner=(g,uid)=>g.state.roster.find(k=>heldItems(g.state,k).some(i=>i.uid===uid));
export function equipmentPanel(g,key){const equipped=heldItems(g.state,key),free=g.state.inventory.filter(i=>!equipped.some(e=>e.key===i.key)),full=equipped.length===3;return `<header><span class="eyebrow">${equipped.length} / 3 EMPLACEMENTS</span><h3>Ses objets équipés</h3><p>Trois objets différents maximum. Leurs bonus se cumulent. Chaque exemplaire ne peut être porté que par un Pokémon à la fois.</p></header><div class="equipment-slots">${Array.from({length:3},(_,slot)=>{const item=equipped[slot];return item?`<article><img src="assets/items/${item.key}.png" alt=""><span>EMPLACEMENT ${slot+1}</span><b>${item.name}</b><p>${item.desc}</p><button data-act="lab-unequip" data-uid="${item.uid}">Retirer</button></article>`:`<article class="empty"><i>＋</i><span>EMPLACEMENT ${slot+1}</span><b>Disponible</b><p>Équipe un type d’objet différent.</p></article>`}).join('')}</div><label class="equipment-picker">Choisir dans le sac<select id="lab-equip-item" ${full?'disabled':''}><option value="">${full?'Les trois emplacements sont occupés':'Choisis un objet'}</option>${free.map(instance=>{const d=ITEMS.find(i=>i.key===instance.key),who=owner(g,instance.uid);return`<option value="${instance.uid}">${d.name}${who?' · porté par '+g.poke(who).name:''}</option>`}).join('')}</select></label><button class="primary" data-act="lab-equip" ${full||!free.length?'disabled':''}>Équiper cet objet</button><p class="sheet-note">Retirer un objet le conserve dans le sac. Si tu déplaces un exemplaire déjà porté, il est retiré de son ancien Pokémon.</p>`}
export function equipmentInventory(g){return g.heading('LES ÉQUIPEMENTS DE TES PARTENAIRES','Sac & objets','Trois objets différents par Pokémon. Compose leurs bonus selon ton style de combat.')+bagHTML(g)+`<div class="equipment-grid">${g.state.roster.map(key=>{const items=heldItems(g.state,key);return`<div class="equipment-mon">${g.image(key)}<b>${g.poke(key).name}</b><small>${items.length} / 3 objets équipés</small><div class="equipment-mini">${Array.from({length:3},(_,i)=>{const item=items.find(x=>x.slot===i);return item?`<img src="assets/items/${item.key}.png" title="${item.name}" alt="${item.name}">`:'<span>＋</span>'}).join('')}</div><button data-act="lab-equipment" data-key="${key}">Gérer ses objets</button></div>`}).join('')}</div><div class="section-title"><h2>Ton sac · ${g.state.inventory.length} objets</h2><span>3 emplacements · Aucun doublon de type</span></div><div class="item-grid">${g.state.inventory.map((instance,index)=>{const d=ITEMS.find(d=>d.key===instance.key),who=owner(g,instance.uid),allowed=g.state.roster.filter(k=>{const used=heldItems(g.state,k);return used.length<3&&!used.some(i=>i.key===d.key)});return`<article class="item-card ${d.rarity}"><span class="rarity-tag ${d.rarity}">${g.rarity(d.rarity).name}</span><img src="assets/items/${d.key}.png" alt="${d.name}"><h3>${d.name}</h3><p>${d.desc}</p><small>${who?'Porté par '+g.poke(who).name:'Disponible dans le sac'}</small><select id="equip-${index}" aria-label="Destinataire pour ${d.name}">${g.state.roster.map(k=>`<option value="${k}" ${!allowed.includes(k)?'disabled':''} ${k===allowed[0]?'selected':''}>${g.poke(k).name} · ${heldItems(g.state,k).length}/3</option>`).join('')}</select><button data-act="equip" data-uid="${instance.uid}" data-index="${index}" ${!allowed.length?'disabled':''}>${who?'Déplacer cet exemplaire':'Équiper'}</button>${who?`<button class="text-button" data-act="unequip" data-key="${who}" data-uid="${instance.uid}">Retirer de ${g.poke(who).name}</button>`:''}</article>`}).join('')||'<div class="panel empty-state"><h2>Ton sac attend ses premiers trésors.</h2><p>Les coffres de survie contiennent des objets à équiper.</p><button data-act="route" data-page="survival">Partir en survie</button></div>'}</div>`}
